SELECT p.product_id, p.name, p.price, p.image_url, p.status, p.stock_quantity, p.main_category, p.created_at, (SELECT COUNT(*) FROM tbl_product_options po WHERE po.product_id = p.product_id) as option_count FROM tbl_products p WHERE 1=1
AND p.main_category = #{mainCategory}
AND ( p.name LIKE CONCAT('%', #{searchKeyword}, '%') OR p.description LIKE CONCAT('%', #{searchKeyword}, '%') )
ORDER BY p.created_at DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM tbl_products WHERE 1=1
AND main_category = #{mainCategory}
AND ( name LIKE CONCAT('%', #{searchKeyword}, '%') OR description LIKE CONCAT('%', #{searchKeyword}, '%') )
